insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$dynasty$t$, $t$Dynasty$t$, $t$ৰাজবংশ$t$, $t$A line of rulers from the same family, where power passes from one generation to the next.$t$, $t$একেটা পৰিয়ালৰ শাসকসকলৰ ধাৰা, য'ত ক্ষমতা এক প্ৰজন্মৰ পৰা আন প্ৰজন্মলৈ যায়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$allahabad-pillar-inscription$t$, $t$Allahabad Pillar Inscription$t$, $t$এলাহাবাদ স্তম্ভলিপি$t$, $t$A 4th-century inscription praising the Gupta emperor Samudragupta. It is the first record to name Kamarupa.$t$, $t$গুপ্ত সম্ৰাট সমুদ্ৰগুপ্তৰ প্ৰশংসা কৰা চতুৰ্থ শতিকাৰ শিলালিপি। ইয়াতেই প্ৰথমবাৰৰ বাবে কামৰূপৰ নাম পোৱা যায়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$xuanzang$t$, $t$Xuanzang (Hiuen Tsang)$t$, $t$হিউৱেন চাং$t$, $t$A Chinese Buddhist monk and traveller of the 7th century who visited India and wrote about Kamarupa.$t$, $t$সপ্তম শতিকাৰ এগৰাকী চীনা বৌদ্ধ ভিক্ষু আৰু পৰিব্ৰাজক, যিয়ে ভাৰত ভ্ৰমণ কৰি কামৰূপৰ বিষয়ে লিখি গৈছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$swargadeo$t$, $t$Swargadeo$t$, $t$স্বৰ্গদেউ$t$, $t$The title of the Ahom kings, meaning 'lord of heaven'. It was first taken by Suhungmung.$t$, $t$আহোম ৰজাসকলৰ উপাধি, যাৰ অৰ্থ 'স্বৰ্গৰ দেৱতা'। চুহুংমুঙে প্ৰথমে এই উপাধি গ্ৰহণ কৰিছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$paik-system$t$, $t$Paik system$t$, $t$পাইক প্ৰথা$t$, $t$The Ahom system in which adult men (paiks) gave labour or military service to the state in turn, in return for land.$t$, $t$আহোম যুগৰ ব্যৱস্থা, য'ত প্ৰাপ্তবয়স্ক পুৰুষসকলে (পাইক) মাটিৰ বিনিময়ত পাল পাতি ৰাজ্যক শ্ৰম বা সামৰিক সেৱা আগবঢ়াইছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$borphukan$t$, $t$Borphukan$t$, $t$বৰফুকন$t$, $t$A high Ahom office: the governor of Lower Assam and commander in the west, based in Guwahati.$t$, $t$আহোম ৰাজ্যৰ এক উচ্চ পদ: গুৱাহাটীত থাকি নামনি অসম শাসন কৰা আৰু পশ্চিমৰ সেনাপতি।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$moamoria-rebellion$t$, $t$Moamoria rebellion$t$, $t$মোৱামৰীয়া বিদ্ৰোহ$t$, $t$A long uprising against the Ahom kings that began in 1769. It badly weakened the kingdom.$t$, $t$১৭৬৯ চনত আৰম্ভ হোৱা আহোম ৰজাসকলৰ বিৰুদ্ধে এক দীঘলীয়া বিদ্ৰোহ। ই ৰাজ্যখনক বহুত দুৰ্বল কৰি পেলাইছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$neo-vaishnavism$t$, $t$Neo-Vaishnavism (Ekasarana Dharma)$t$, $t$নৱ-বৈষ্ণৱ ধৰ্ম (একশৰণ নামধৰ্ম)$t$, $t$The devotional faith founded by Srimanta Sankardev, centred on prayer to one god (Krishna) through singing his name.$t$, $t$শ্ৰীমন্ত শংকৰদেৱে প্ৰতিষ্ঠা কৰা ভক্তিধৰ্ম, য'ত নাম-কীৰ্তনৰ জৰিয়তে এক ঈশ্বৰ (কৃষ্ণ)ৰ শৰণ লোৱা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$mughal$t$, $t$Mughals$t$, $t$মোগল$t$, $t$The empire that ruled most of North India from Delhi and Agra from the 16th to the 18th century.$t$, $t$ষোড়শৰ পৰা অষ্টাদশ শতিকালৈ দিল্লী আৰু আগ্ৰাৰ পৰা উত্তৰ ভাৰতৰ বেছিভাগ অঞ্চল শাসন কৰা সাম্ৰাজ্য।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$maan$t$, $t$Maan (Burmese)$t$, $t$মান$t$, $t$The Assamese name for the Burmese, who invaded Assam three times between 1817 and 1826.$t$, $t$বৰ্মীসকলৰ অসমীয়া নাম। তেওঁলোকে ১৮১৭ ৰ পৰা ১৮২৬ চনৰ ভিতৰত তিনিবাৰ অসম আক্ৰমণ কৰিছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$dewan$t$, $t$Dewan$t$, $t$দেৱান$t$, $t$A chief officer or manager. Maniram Dewan got this title as an officer of the Assam Tea Company.$t$, $t$মুখ্য বিষয়া বা পৰিচালক। আসাম টি কোম্পানীৰ বিষয়া হিচাপে মণিৰামে এই উপাধি পাইছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$quit-india-movement$t$, $t$Quit India Movement$t$, $t$ভাৰত ত্যাগ আন্দোলন$t$, $t$The 1942 movement led by Mahatma Gandhi demanding that the British leave India at once.$t$, $t$ব্ৰিটিছক তৎক্ষণাত ভাৰত এৰি যাবলৈ দাবী জনাই মহাত্মা গান্ধীৰ নেতৃত্বত ১৯৪২ চনত হোৱা আন্দোলন।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$mrityu-bahini$t$, $t$Mrityu Bahini$t$, $t$মৃত্যু বাহিনী$t$, $t$A 'death squad' of young volunteers from Gohpur who were ready to die for freedom during the Quit India Movement.$t$, $t$ভাৰত ত্যাগ আন্দোলনৰ সময়ত স্বাধীনতাৰ বাবে প্ৰাণ দিবলৈ সাজু থকা গহপুৰৰ যুৱ স্বেচ্ছাসেৱকৰ দল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$cabinet-mission$t$, $t$Cabinet Mission (1946)$t$, $t$কেবিনেট মিছন (১৯৪৬)$t$, $t$A team of British ministers sent to India in 1946 to plan the transfer of power. Its plan grouped Assam with Bengal.$t$, $t$ক্ষমতা হস্তান্তৰৰ পৰিকল্পনা কৰিবলৈ ১৯৪৬ চনত ভাৰতলৈ পঠোৱা ব্ৰিটিছ মন্ত্ৰীৰ দল। ইয়াৰ পৰিকল্পনাত অসমক বংগৰ সৈতে একেটা গোটত ৰখা হৈছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$assam-accord$t$, $t$Assam Accord$t$, $t$অসম চুক্তি$t$, $t$The agreement signed on 15 August 1985 between the Government of India and the leaders of the Assam Movement.$t$, $t$১৯৮৫ চনৰ ১৫ আগষ্টত ভাৰত চৰকাৰ আৰু অসম আন্দোলনৰ নেতাসকলৰ মাজত স্বাক্ষৰিত চুক্তি।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$aasu$t$, $t$AASU$t$, $t$আছু$t$, $t$All Assam Students' Union, the students' body that led the Assam Movement.$t$, $t$সদৌ অসম ছাত্ৰ সন্থা, যিয়ে অসম আন্দোলনৰ নেতৃত্ব দিছিল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$cut-off-date$t$, $t$Cut-off date$t$, $t$ভিত্তি তাৰিখ$t$, $t$A fixed date used as a dividing line. In the Assam Accord it decides which migrants are to be detected.$t$, $t$বিভাজন ৰেখা হিচাপে লোৱা এটা নিৰ্দিষ্ট তাৰিখ। অসম চুক্তিত কোনবোৰ প্ৰব্ৰজনকাৰী চিনাক্ত কৰা হ'ব, সেয়া ইয়াৰ দ্বাৰা নিৰ্ধাৰণ হয়।$t$) on conflict (slug) do nothing;
insert into public.content (slug, kind, category_id, position) select $t$ancient-assam-kamarupa$t$, 'gk_chapter', id, 1 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Ancient Assam: Pragjyotisha and Kamarupa$t$, $t$The kingdom of Kamarupa (350 to 1140 CE) and its three dynasties.$t$, 'draft', $t$Kamarupa, Wikipedia: https://en.wikipedia.org/wiki/Kamarupa$t$, date '2026-11-24' from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$In ancient times the land of Assam was known as {{term:pragjyotisha|Pragjyotisha}} and {{term:kamarupa|Kamarupa}}. The historical kingdom of Kamarupa lasted from about 350 to 1140 CE.$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$The first record that names Kamarupa is the 4th-century {{term:allahabad-pillar-inscription|Allahabad Pillar Inscription}} of the Gupta emperor Samudragupta. It calls the rulers of Kamarupa 'frontier rulers'.$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Three dynasties of Kamarupa$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 4, 'list', 'event', $t$Varman {{term:dynasty}}: founded by Pushyavarman (350 to 374 CE).
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 5, 'heading', 'normal', $t$Bhaskaravarman$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 6, 'paragraph', 'personality', $t$Bhaskaravarman (ruled 600 to 650 CE) was the most famous Varman king. In 606 CE he made an alliance with Harshavardhana of Kanauj. The Chinese traveller {{term:xuanzang|Xuanzang}} wrote about his kingdom.$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$The kingdom of Kamarupa broke up by the 12th to 13th century, and smaller kingdoms took its place.$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Kamarupa is first named in the Allahabad Pillar Inscription. Dynasties in order: Varman, Mlechchha, Pala. Most famous king: Bhaskaravarman.$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$প্ৰাচীন অসম: প্ৰাগজ্যোতিষ আৰু কামৰূপ$t$, $t$কামৰূপ ৰাজ্য (৩৫০ ৰ পৰা ১১৪০ খ্ৰীষ্টাব্দ) আৰু ইয়াৰ তিনিটা ৰাজবংশ।$t$, 'draft', $t$Kamarupa, Wikipedia: https://en.wikipedia.org/wiki/Kamarupa$t$, date '2026-11-24' from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$প্ৰাচীন কালত অসমৰ ভূমি {{term:pragjyotisha|প্ৰাগজ্যোতিষ}} আৰু {{term:kamarupa|কামৰূপ}} নামেৰে জনাজাত আছিল। ঐতিহাসিক কামৰূপ ৰাজ্য প্ৰায় ৩৫০ ৰ পৰা ১১৪০ খ্ৰীষ্টাব্দলৈ আছিল।$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$কামৰূপৰ নাম প্ৰথমে পোৱা যায় গুপ্ত সম্ৰাট সমুদ্ৰগুপ্তৰ চতুৰ্থ শতিকাৰ {{term:allahabad-pillar-inscription|এলাহাবাদ স্তম্ভলিপিত}}। ইয়াত কামৰূপৰ শাসকসকলক 'সীমান্তৰ ৰজা' বুলি কোৱা হৈছে।$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$কামৰূপৰ তিনিটা ৰাজবংশ$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 4, 'list', 'event', $t$বৰ্মন {{term:dynasty|ৰাজবংশ}}: প্ৰতিষ্ঠাপক পুষ্যবৰ্মন (৩৫০ ৰ পৰা ৩৭৪ খ্ৰীষ্টাব্দ)।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 5, 'heading', 'normal', $t$ভাস্কৰবৰ্মন$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 6, 'paragraph', 'personality', $t$ভাস্কৰবৰ্মন (৬০০ ৰ পৰা ৬৫০ খ্ৰীষ্টাব্দ) বৰ্মন বংশৰ আটাইতকৈ বিখ্যাত ৰজা আছিল। ৬০৬ খ্ৰীষ্টাব্দত তেওঁ কনৌজৰ হৰ্ষবৰ্ধনৰ সৈতে মিত্ৰতা গঢ়ে। চীনা পৰিব্ৰাজক {{term:xuanzang|হিউৱেন চাঙে}} তেওঁৰ ৰাজ্যৰ বিষয়ে লিখি গৈছে।$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$দ্বাদশৰ পৰা ত্ৰয়োদশ শতিকাৰ ভিতৰত কামৰূপ ৰাজ্য ভাগি পৰে আৰু তাৰ ঠাইত সৰু সৰু ৰাজ্যৰ উদ্ভৱ হয়।$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: কামৰূপৰ নাম প্ৰথমে এলাহাবাদ স্তম্ভলিপিত পোৱা যায়। ৰাজবংশৰ ক্ৰম: বৰ্মন, ম্লেচ্ছ, পাল। আটাইতকৈ বিখ্যাত ৰজা: ভাস্কৰবৰ্মন।$t$ from public.content where slug = $t$ancient-assam-kamarupa$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$ahom-kingdom$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The Ahom kingdom (1228 to 1826)$t$, $t$Sukaphaa, the capitals, the great kings and the fall of the Ahom kingdom.$t$, 'draft', $t$Ahom kingdom, Wikipedia: https://en.wikipedia.org/wiki/Ahom_kingdom$t$, date '2026-11-24' from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The {{term:ahom|Ahom}} kingdom ruled the Brahmaputra Valley for about 598 years, from 1228 to 1826. It was founded by Sukaphaa, a Tai prince from Mong Mao, who crossed the Patkai hills and entered the valley in 1228.$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Capitals of the Ahom kingdom$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 3, 'list', 'heritage', $t$Charaideo (from 1253), the first capital
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$The kingdom was organised on the {{term:paik-system|Paik system}}, under which men served the state in turn.$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 5, 'heading', 'normal', $t$Important kings$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l2', 6, 'list', 'personality', $t$Suhungmung, the Dihingia Raja (1497 to 1539): took the title {{term:swargadeo|Swargadeo}}; annexed the Chutia kingdom in 1523.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 7, 'paragraph', 'normal', $t$The {{term:moamoria-rebellion|Moamoria rebellion}}, which began in 1769, weakened the kingdom. The Burmese invasions followed, and in 1826 Assam passed to the British.$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: founder Sukaphaa (1228); first capital Charaideo; first king to be called Swargadeo: Suhungmung.$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$আহোম ৰাজ্য (১২২৮ ৰ পৰা ১৮২৬)$t$, $t$চুকাফা, ৰাজধানীসমূহ, প্ৰসিদ্ধ ৰজাসকল আৰু আহোম ৰাজ্যৰ পতন।$t$, 'draft', $t$Ahom kingdom, Wikipedia: https://en.wikipedia.org/wiki/Ahom_kingdom$t$, date '2026-11-24' from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:ahom|আহোম}} ৰাজ্যই ১২২৮ ৰ পৰা ১৮২৬ চনলৈ প্ৰায় ৫৯৮ বছৰ ব্ৰহ্মপুত্ৰ উপত্যকা শাসন কৰিছিল। মং মাওৰ টাই ৰাজকুমাৰ চুকাফাই ১২২৮ চনত পাটকাই পাহাৰ পাৰ হৈ উপত্যকালৈ আহি এই ৰাজ্য প্ৰতিষ্ঠা কৰে।$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$আহোম ৰাজ্যৰ ৰাজধানীসমূহ$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 3, 'list', 'heritage', $t$চৰাইদেউ (১২৫৩ চনৰ পৰা), প্ৰথম ৰাজধানী
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$ৰাজ্যখন {{term:paik-system|পাইক প্ৰথাৰ}} ওপৰত গঢ় লৈ উঠিছিল, য'ত পুৰুষসকলে পাল পাতি ৰাজ্যৰ সেৱা কৰিছিল।$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 5, 'heading', 'normal', $t$প্ৰসিদ্ধ ৰজাসকল$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l2', 6, 'list', 'personality', $t$চুহুংমুং, দিহিঙীয়া ৰজা (১৪৯৭ ৰ পৰা ১৫৩৯): {{term:swargadeo|স্বৰ্গদেউ}} উপাধি লয়; ১৫২৩ চনত চুতীয়া ৰাজ্য অধিকাৰ কৰে।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 7, 'paragraph', 'normal', $t$১৭৬৯ চনত আৰম্ভ হোৱা {{term:moamoria-rebellion|মোৱামৰীয়া বিদ্ৰোহে}} ৰাজ্যখন দুৰ্বল কৰে। তাৰ পিছত মানৰ আক্ৰমণ হয় আৰু ১৮২৬ চনত অসম ব্ৰিটিছৰ হাতলৈ যায়।$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: প্ৰতিষ্ঠাপক চুকাফা (১২২৮); প্ৰথম ৰাজধানী চৰাইদেউ; প্ৰথম স্বৰ্গদেউ উপাধি লোৱা ৰজা: চুহুংমুং।$t$ from public.content where slug = $t$ahom-kingdom$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$koch-kingdom$t$, 'gk_chapter', id, 3 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The Koch kingdom$t$, $t$Biswa Singha, Nara Narayan and Chilarai, and the split into Koch Bihar and Koch Hajo.$t$, 'draft', $t$Koch dynasty, Wikipedia: https://en.wikipedia.org/wiki/Koch_dynasty$t$, date '2026-11-24' from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Koch {{term:dynasty}} rose in western Assam and North Bengal. Biswa Singha established its power in 1515 and ruled until 1540.$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'personality', $t$Under his son Nara Narayan (ruled 1540 to 1586), the kingdom reached its height. His brother Chilarai (Shukladhwaj) was the commander of the army; in 1562 he took the Barak Valley from the Tripura kingdom.$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'heritage', $t$Srimanta Sankardev and his disciples Madhavdev and Damodardev spread {{term:neo-vaishnavism|Neo-Vaishnavism}} in the Koch kingdom, and the Koch rulers supported the Sattras they founded.$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 4, 'paragraph', 'normal', $t$After Nara Narayan, Chilarai's son Raghudev, governor of Koch Hajo, declared independence. In 1587 the kingdom was divided into Koch Bihar in the west and Koch Hajo in the east.$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: founder Biswa Singha (1515); greatest king Nara Narayan; general Chilarai; split in 1587.$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$কোচ ৰাজ্য$t$, $t$বিশ্ব সিংহ, নৰনাৰায়ণ আৰু চিলাৰায়, আৰু কোচ বিহাৰ আৰু কোচ হাজোলৈ বিভাজন।$t$, 'draft', $t$Koch dynasty, Wikipedia: https://en.wikipedia.org/wiki/Koch_dynasty$t$, date '2026-11-24' from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$কোচ {{term:dynasty|ৰাজবংশ}} পশ্চিম অসম আৰু উত্তৰ বংগত গঢ় লৈ উঠে। বিশ্ব সিংহই ১৫১৫ চনত ইয়াৰ শাসন প্ৰতিষ্ঠা কৰে আৰু ১৫৪০ চনলৈ ৰাজত্ব কৰে।$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'personality', $t$তেওঁৰ পুত্ৰ নৰনাৰায়ণৰ (১৫৪০ ৰ পৰা ১৫৮৬) দিনত ৰাজ্যখন উন্নতিৰ শিখৰত উঠে। তেওঁৰ ভাতৃ চিলাৰায় (শুক্লধ্বজ) সেনাপতি আছিল; ১৫৬২ চনত তেওঁ ত্ৰিপুৰা ৰাজ্যৰ পৰা বৰাক উপত্যকা অধিকাৰ কৰে।$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'heritage', $t$শ্ৰীমন্ত শংকৰদেৱ আৰু তেওঁৰ শিষ্য মাধৱদেৱ আৰু দামোদৰদেৱে কোচ ৰাজ্যত {{term:neo-vaishnavism|নৱ-বৈষ্ণৱ ধৰ্ম}} প্ৰচাৰ কৰে, আৰু কোচ ৰজাসকলে তেওঁলোকে প্ৰতিষ্ঠা কৰা সত্ৰসমূহক পৃষ্ঠপোষকতা কৰে।$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 4, 'paragraph', 'normal', $t$নৰনাৰায়ণৰ পিছত কোচ হাজোৰ শাসনকৰ্তা চিলাৰায়ৰ পুত্ৰ ৰঘুদেৱে স্বাধীনতা ঘোষণা কৰে। ১৫৮৭ চনত ৰাজ্যখন পশ্চিমত কোচ বিহাৰ আৰু পূবত কোচ হাজো, এই দুভাগত বিভক্ত হয়।$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: প্ৰতিষ্ঠাপক বিশ্ব সিংহ (১৫১৫); শ্ৰেষ্ঠ ৰজা নৰনাৰায়ণ; সেনাপতি চিলাৰায়; বিভাজন ১৫৮৭ চনত।$t$ from public.content where slug = $t$koch-kingdom$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$mughal-invasions-saraighat$t$, 'gk_chapter', id, 4 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Mughal invasions and the Battle of Saraighat$t$, $t$How the Ahoms under Lachit Borphukan stopped the Mughals at Saraighat in 1671.$t$, 'draft', $t$Battle of Saraighat, Wikipedia: https://en.wikipedia.org/wiki/Battle_of_Saraighat
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The {{term:mughal|Mughals}} attacked the Ahom kingdom several times in the 17th century. In 1662 to 1663 the Mughal general Mir Jumla invaded, and the war ended with the Treaty of Ghilajharighat in January 1663.$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$The Ahoms later won back Guwahati. The Mughals sent a large army under Ram Singh I, the Kachwaha raja of Amber. The Battle of Alaboi was fought around 5 August 1669.$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$The Battle of Saraighat (1671)$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'event', $t$In the middle of March 1671, the Ahom army led by {{term:borphukan|Borphukan}} Lachit fought the Mughal fleet on the Brahmaputra at Saraighat, in present-day Guwahati. The Ahoms won, and the Mughal admiral Munnawar Khan was killed.$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$At the start of the campaign the Ahom king was Chakradhwaj Singha; after his death his brother Udayaditya Singha became king.$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 6, 'paragraph', 'normal', $t$In 1682, at the Battle of Itakhuli, the Ahoms defeated the Mughals again, and the Manas river became the western boundary of the kingdom.$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: Saraighat, 1671; Lachit Borphukan against Ram Singh I; Itakhuli, 1682.$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$মোগল আক্ৰমণ আৰু শৰাইঘাটৰ যুদ্ধ$t$, $t$১৬৭১ চনত লাচিত বৰফুকনৰ নেতৃত্বত আহোমসকলে কেনেকৈ শৰাইঘাটত মোগলক ৰুধিছিল।$t$, 'draft', $t$Battle of Saraighat, Wikipedia: https://en.wikipedia.org/wiki/Battle_of_Saraighat
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$সপ্তদশ শতিকাত {{term:mughal|মোগলসকলে}} কেইবাবাৰো আহোম ৰাজ্য আক্ৰমণ কৰিছিল। ১৬৬২-৬৩ চনত মোগল সেনাপতি মীৰজুমলাই আক্ৰমণ কৰে, আৰু ১৬৬৩ চনৰ জানুৱাৰীত ঘিলাঝাৰিঘাটৰ সন্ধিৰে সেই যুদ্ধৰ অন্ত পৰে।$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$পিছত আহোমসকলে গুৱাহাটী পুনৰ দখল কৰে। মোগলে অম্বৰৰ কাছোৱা ৰজা প্ৰথম ৰামসিংহৰ নেতৃত্বত এক বিশাল বাহিনী পঠায়। ১৬৬৯ চনৰ প্ৰায় ৫ আগষ্টত আলাবৈৰ যুদ্ধ হয়।$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$শৰাইঘাটৰ যুদ্ধ (১৬৭১)$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'event', $t$১৬৭১ চনৰ মাৰ্চ মাহৰ মাজভাগত {{term:borphukan|বৰফুকন}} লাচিতৰ নেতৃত্বত আহোম সেনাই বৰ্তমানৰ গুৱাহাটীৰ শৰাইঘাটত ব্ৰহ্মপুত্ৰৰ বুকুত মোগল নৌবাহিনীৰ সৈতে যুদ্ধ কৰে। আহোমসকল জয়ী হয় আৰু মোগল নৌ-সেনাপতি মুন্নাৱৰ খান নিহত হয়।$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$অভিযানৰ আৰম্ভণিতে আহোম ৰজা আছিল চক্ৰধ্বজ সিংহ; তেওঁৰ মৃত্যুৰ পিছত তেওঁৰ ভাতৃ উদয়াদিত্য সিংহ ৰজা হয়।$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 6, 'paragraph', 'normal', $t$১৬৮২ চনত ইটাখুলিৰ যুদ্ধত আহোমসকলে পুনৰ মোগলক পৰাস্ত কৰে আৰু মানস নদী ৰাজ্যৰ পশ্চিম সীমা হয়।$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: শৰাইঘাট, ১৬৭১; লাচিত বৰফুকন বনাম প্ৰথম ৰামসিংহ; ইটাখুলি, ১৬৮২।$t$ from public.content where slug = $t$mughal-invasions-saraighat$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$burmese-invasions-yandabo$t$, 'gk_chapter', id, 5 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Burmese invasions and the Treaty of Yandabo$t$, $t$The three Burmese invasions (1817 to 1826) and how Assam passed to the British.$t$, 'draft', $t$Burmese invasions of Assam, Wikipedia: https://en.wikipedia.org/wiki/Burmese_invasions_of_Assam$t$, date '2026-11-24' from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Between 1817 and 1826 the {{term:maan|Burmese (Maan)}} invaded Assam three times. Quarrels among Ahom nobles opened the way: Badan Chandra Borphukan, governor of Guwahati, had asked the Burmese king Bodawpaya for help in 1816.$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'event', $t$First invasion (1817): the Burmese army entered in January 1817. Chandrakanta Singha was the Ahom king.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$Burmese rule (1821 to 1825) is remembered as a time of great suffering. The British then fought the Burmese in the First Anglo-Burmese War.$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'event', $t$The war ended with the {{term:treaty-of-yandabo|Treaty of Yandabo}} in 1826. Burmese rule in Assam ended and British rule began.$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: Burmese invasions 1817, 1819 and 1821; Treaty of Yandabo 1826.$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$মানৰ আক্ৰমণ আৰু ইয়াণ্ডাবুৰ সন্ধি$t$, $t$মানৰ তিনিটা আক্ৰমণ (১৮১৭ ৰ পৰা ১৮২৬) আৰু অসম কেনেকৈ ব্ৰিটিছৰ হাতলৈ গ'ল।$t$, 'draft', $t$Burmese invasions of Assam, Wikipedia: https://en.wikipedia.org/wiki/Burmese_invasions_of_Assam$t$, date '2026-11-24' from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$১৮১৭ ৰ পৰা ১৮২৬ চনৰ ভিতৰত {{term:maan|মানে}} তিনিবাৰ অসম আক্ৰমণ কৰে। আহোম বিষয়াসকলৰ ভিতৰুৱা কাজিয়াই ইয়াৰ বাট মুকলি কৰে: গুৱাহাটীৰ শাসনকৰ্তা বদনচন্দ্ৰ বৰফুকনে ১৮১৬ চনত মান ৰজা বদ'পায়াৰ সহায় বিচাৰিছিল।$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'event', $t$প্ৰথম আক্ৰমণ (১৮১৭): ১৮১৭ চনৰ জানুৱাৰীত মান সেনা প্ৰৱেশ কৰে। তেতিয়া আহোম ৰজা আছিল চন্দ্ৰকান্ত সিংহ।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$মানৰ শাসনকাল (১৮২১ ৰ পৰা ১৮২৫) অসমৰ বাবে অতি দুখৰ সময় হিচাপে স্মৰণীয়। তাৰ পিছত ব্ৰিটিছে প্ৰথম ইংগ-বৰ্মী যুদ্ধত মানৰ বিৰুদ্ধে যুঁজ দিয়ে।$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'event', $t$১৮২৬ চনত {{term:treaty-of-yandabo|ইয়াণ্ডাবুৰ সন্ধিৰে}} যুদ্ধৰ অন্ত পৰে। অসমত মানৰ শাসন শেষ হয় আৰু ব্ৰিটিছৰ শাসন আৰম্ভ হয়।$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: মানৰ আক্ৰমণ ১৮১৭, ১৮১৯ আৰু ১৮২১; ইয়াণ্ডাবুৰ সন্ধি ১৮২৬।$t$ from public.content where slug = $t$burmese-invasions-yandabo$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$assam-under-british-rule$t$, 'gk_chapter', id, 6 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Assam under British rule$t$, $t$Early British rule, tea, and the first revolts: Gomdhar Konwar, Maniram Dewan and Phulaguri.$t$, 'draft', $t$Assam, Wikipedia: https://en.wikipedia.org/wiki/Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$After the {{term:treaty-of-yandabo|Treaty of Yandabo}} (1826), the East India Company took Lower Assam. In 1833 it made Purandar Singha king of Upper Assam, but this lasted only until 1838, after which the British took over the whole region.$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Early revolts$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 3, 'list', 'event', $t$Gomdhar Konwar, an Ahom prince, was declared king at Toratoli near Jorhat and rose against the British. He was defeated, sentenced to death, and the sentence was changed to seven years' banishment.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 4, 'heading', 'normal', $t$Tea comes to Assam$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 5, 'paragraph', 'normal', $t$In 1839, Maniram became the {{term:dewan|Dewan}} of the Assam Tea Company at Nazira. He later started his own tea garden at Cinnamara and is called the first Indian tea planter to grow tea commercially in Assam.$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Maniram Dewan and Piyali Barua hanged 26 February 1858; Phulaguri Dhewa 1861.$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$ব্ৰিটিছ শাসনত অসম$t$, $t$প্ৰাৰম্ভিক ব্ৰিটিছ শাসন, চাহ, আৰু প্ৰথম বিদ্ৰোহ: গোমধৰ কোঁৱৰ, মণিৰাম দেৱান আৰু ফুলগুৰি।$t$, 'draft', $t$Assam, Wikipedia: https://en.wikipedia.org/wiki/Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:treaty-of-yandabo|ইয়াণ্ডাবুৰ সন্ধিৰ}} (১৮২৬) পিছত ইষ্ট ইণ্ডিয়া কোম্পানীয়ে নামনি অসম অধিকাৰ কৰে। ১৮৩৩ চনত কোম্পানীয়ে পুৰন্দৰ সিংহক উজনি অসমৰ ৰজা পাতে, কিন্তু সেয়া ১৮৩৮ চনলৈহে থাকে; তাৰ পিছত ব্ৰিটিছে গোটেই অঞ্চল অধিকাৰ কৰে।$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$প্ৰথম বিদ্ৰোহসমূহ$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 3, 'list', 'event', $t$আহোম ৰাজকুমাৰ গোমধৰ কোঁৱৰক যোৰহাটৰ ওচৰৰ টৰাটলিত ৰজা ঘোষণা কৰা হয় আৰু তেওঁ ব্ৰিটিছৰ বিৰুদ্ধে বিদ্ৰোহ কৰে। তেওঁ পৰাস্ত হয়, মৃত্যুদণ্ড বিহা হয়, পিছত সেই দণ্ড সাত বছৰৰ নিৰ্বাসনলৈ সলনি কৰা হয়।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 4, 'heading', 'normal', $t$অসমলৈ চাহৰ আগমন$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 5, 'paragraph', 'normal', $t$১৮৩৯ চনত মণিৰাম নাজিৰাৰ আসাম টি কোম্পানীৰ {{term:dewan|দেৱান}} হয়। পিছত তেওঁ চিনামৰাত নিজৰ চাহ বাগিচা আৰম্ভ কৰে আৰু অসমত বাণিজ্যিকভাৱে চাহ খেতি কৰা প্ৰথম ভাৰতীয় চাহ খেতিয়ক বুলি তেওঁক কোৱা হয়।$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: মণিৰাম দেৱান আৰু পিয়লি বৰুৱাৰ ফাঁচি ২৬ ফেব্ৰুৱাৰী ১৮৫৮; ফুলগুৰি ধেৱা ১৮৬১।$t$ from public.content where slug = $t$assam-under-british-rule$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$assam-freedom-struggle$t$, 'gk_chapter', id, 7 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Assam in the freedom struggle$t$, $t$Kanaklata Barua and the Quit India Movement, and how Gopinath Bordoloi kept Assam in India.$t$, 'draft', $t$Kanaklata Barua, Wikipedia: https://en.wikipedia.org/wiki/Kanaklata_Barua
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$People from every part of Assam took part in India's struggle for freedom. Two names stand out in exam questions: Kanaklata Barua and Gopinath Bordoloi.$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Kanaklata Barua and the Quit India Movement$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'personality', $t$During the {{term:quit-india-movement|Quit India Movement}} of 1942, Kanaklata Barua of Borangabari, Gohpur, joined the {{term:mrityu-bahini|Mrityu Bahini}}. On 20 September 1942 she was shot dead by the police while leading a procession carrying the national flag. She was 17 years old.$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 4, 'heading', 'normal', $t$Gopinath Bordoloi$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'personality', $t$Gopinath Bordoloi (6 June 1890 to 5 August 1950) became Premier of Assam in 1938. In 1946 the {{term:cabinet-mission|Cabinet Mission}} plan placed Assam in a group with Bengal. The Assam Congress, under Bordoloi, opposed this grouping, which helped Assam stay in India.$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 6, 'paragraph', 'normal', $t$He was the first Chief Minister of Assam, from 11 February 1946 until his death on 5 August 1950. He was given the Bharat Ratna after his death, in 1999.$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: Kanaklata Barua, martyred at Gohpur on 20 September 1942; Gopinath Bordoloi, first Chief Minister, Bharat Ratna 1999.$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$স্বাধীনতা সংগ্ৰামত অসম$t$, $t$কনকলতা বৰুৱা আৰু ভাৰত ত্যাগ আন্দোলন, আৰু গোপীনাথ বৰদলৈয়ে কেনেকৈ অসমক ভাৰতত ৰাখিলে।$t$, 'draft', $t$Kanaklata Barua, Wikipedia: https://en.wikipedia.org/wiki/Kanaklata_Barua
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$ভাৰতৰ স্বাধীনতা সংগ্ৰামত অসমৰ সকলো প্ৰান্তৰ মানুহে অংশ লৈছিল। পৰীক্ষাৰ প্ৰশ্নত দুটা নাম বিশেষভাৱে আহে: কনকলতা বৰুৱা আৰু গোপীনাথ বৰদলৈ।$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$কনকলতা বৰুৱা আৰু ভাৰত ত্যাগ আন্দোলন$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'personality', $t$১৯৪২ চনৰ {{term:quit-india-movement|ভাৰত ত্যাগ আন্দোলনৰ}} সময়ত গহপুৰৰ বৰঙাবাৰীৰ কনকলতা বৰুৱা {{term:mrityu-bahini|মৃত্যু বাহিনীত}} যোগ দিয়ে। ১৯৪২ চনৰ ২০ ছেপ্টেম্বৰত ৰাষ্ট্ৰীয় পতাকা লৈ এক শোভাযাত্ৰাৰ নেতৃত্ব দি থাকোঁতে আৰক্ষীৰ গুলীত তেওঁ শ্বহীদ হয়। তেতিয়া তেওঁৰ বয়স আছিল ১৭ বছৰ।$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 4, 'heading', 'normal', $t$গোপীনাথ বৰদলৈ$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'personality', $t$গোপীনাথ বৰদলৈ (৬ জুন ১৮৯০ ৰ পৰা ৫ আগষ্ট ১৯৫০) ১৯৩৮ চনত অসমৰ প্ৰধানমন্ত্ৰী হয়। ১৯৪৬ চনত {{term:cabinet-mission|কেবিনেট মিছনৰ}} পৰিকল্পনাত অসমক বংগৰ সৈতে একেটা গোটত ৰখা হৈছিল। বৰদলৈৰ নেতৃত্বত অসম কংগ্ৰেছে এই গোটকৰণৰ বিৰোধিতা কৰে, যাৰ ফলত অসম ভাৰততে থাকিবলৈ সক্ষম হয়।$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 6, 'paragraph', 'normal', $t$তেওঁ ১৯৪৬ চনৰ ১১ ফেব্ৰুৱাৰীৰ পৰা ১৯৫০ চনৰ ৫ আগষ্টত মৃত্যু হোৱালৈকে অসমৰ প্ৰথম মুখ্যমন্ত্ৰী আছিল। মৃত্যুৰ পিছত ১৯৯৯ চনত তেওঁক ভাৰতৰত্ন প্ৰদান কৰা হয়।$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: কনকলতা বৰুৱা, ২০ ছেপ্টেম্বৰ ১৯৪২ত গহপুৰত শ্বহীদ; গোপীনাথ বৰদলৈ, প্ৰথম মুখ্যমন্ত্ৰী, ভাৰতৰত্ন ১৯৯৯।$t$ from public.content where slug = $t$assam-freedom-struggle$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$assam-movement-accord$t$, 'gk_chapter', id, 8 from public.categories where slug = $t$history$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The Assam Movement and the Assam Accord$t$, $t$The six-year movement (1979 to 1985) and the Assam Accord of 15 August 1985.$t$, 'draft', $t$Assam Movement, Wikipedia: https://en.wikipedia.org/wiki/Assam_Movement
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Assam Movement (1979 to 1985) was a mass movement against illegal immigration into Assam. It was led by the {{term:aasu|All Assam Students' Union (AASU)}} and the All Assam Gana Sangram Parishad (AAGSP).$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$The immediate trigger was the by-election in Mangaldoi in 1979, when a large number of names on the voters' list were questioned. AASU's 12-hour general strike on 8 June 1979 is taken as the start of the movement.$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$The Assam Accord (1985)$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'event', $t$The {{term:assam-accord|Assam Accord}} was signed on 15 August 1985 in New Delhi, in the presence of Prime Minister Rajiv Gandhi. Prafulla Kumar Mahanta and Bhrigu Kumar Phukan of AASU and Biraj Kumar Sarma of AAGSP signed for the movement.$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 5, 'list', 'verified_fact', $t$People who came to Assam before 1 January 1966 are accepted as citizens.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 6, 'paragraph', 'normal', $t$Over 855 people lost their lives during the movement.$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 7, 'paragraph', 'normal', $t$After the Accord, the movement's leaders formed a political party, the Asom Gana Parishad (AGP), which won the election, and Prafulla Kumar Mahanta became Chief Minister in 1985.$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Assam Accord signed 15 August 1985; cut-off date 25 March 1971; Clause 6 protects the Assamese people.$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসম আন্দোলন আৰু অসম চুক্তি$t$, $t$ছবছৰীয়া আন্দোলন (১৯৭৯ ৰ পৰা ১৯৮৫) আৰু ১৯৮৫ চনৰ ১৫ আগষ্টৰ অসম চুক্তি।$t$, 'draft', $t$Assam Movement, Wikipedia: https://en.wikipedia.org/wiki/Assam_Movement
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসম আন্দোলন (১৯৭৯ ৰ পৰা ১৯৮৫) অসমলৈ হোৱা অবৈধ প্ৰব্ৰজনৰ বিৰুদ্ধে এক গণ আন্দোলন আছিল। ইয়াৰ নেতৃত্ব দিছিল {{term:aasu|সদৌ অসম ছাত্ৰ সন্থা (আছু)}} আৰু সদৌ অসম গণ সংগ্ৰাম পৰিষদে।$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$১৯৭৯ চনৰ মঙলদৈৰ উপ-নিৰ্বাচনত ভোটাৰ তালিকাৰ বহুতো নাম সন্দেহৰ আওতালৈ অহাটোৱেই ইয়াৰ তাৎক্ষণিক কাৰণ আছিল। ১৯৭৯ চনৰ ৮ জুনত আছুৱে আহ্বান কৰা ১২ ঘণ্টীয়া বন্ধক আন্দোলনৰ আৰম্ভণি বুলি ধৰা হয়।$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$অসম চুক্তি (১৯৮৫)$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'event', $t$১৯৮৫ চনৰ ১৫ আগষ্টত নতুন দিল্লীত প্ৰধানমন্ত্ৰী ৰাজীৱ গান্ধীৰ উপস্থিতিত {{term:assam-accord|অসম চুক্তি}} স্বাক্ষৰিত হয়। আন্দোলনৰ হৈ আছুৰ প্ৰফুল্ল কুমাৰ মহন্ত আৰু ভৃগু কুমাৰ ফুকন আৰু গণ সংগ্ৰাম পৰিষদৰ বিৰাজ কুমাৰ শৰ্মাই স্বাক্ষৰ কৰে।$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 5, 'list', 'verified_fact', $t$১৯৬৬ চনৰ ১ জানুৱাৰীৰ আগতে অসমলৈ অহা লোকসকলক নাগৰিক হিচাপে গ্ৰহণ কৰা হ'ব।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 6, 'paragraph', 'normal', $t$আন্দোলনৰ সময়ত ৮৫৫ জনতকৈ অধিক লোকে প্ৰাণ আহুতি দিয়ে।$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 7, 'paragraph', 'normal', $t$চুক্তিৰ পিছত আন্দোলনৰ নেতাসকলে অসম গণ পৰিষদ (অগপ) নামৰ ৰাজনৈতিক দল গঠন কৰে, যিয়ে নিৰ্বাচনত জয়লাভ কৰে, আৰু ১৯৮৫ চনত প্ৰফুল্ল কুমাৰ মহন্ত মুখ্যমন্ত্ৰী হয়।$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: অসম চুক্তি ১৫ আগষ্ট ১৯৮৫; ভিত্তি তাৰিখ ২৫ মাৰ্চ ১৯৭১; ৬ নং দফাই অসমীয়া জনগণক সুৰক্ষা দিয়ে।$t$ from public.content where slug = $t$assam-movement-accord$t$ on conflict do nothing;
